func isCaddyfile(configFile, adapterName string) (bool, error) {
	if adapterName == "caddyfile" {
		selected := caddyconfig.GetAdapter(adapterName)
		modInfo, err := caddy.GetModule("caddy.adapters.caddyfile")
		adapterPresent := selected != nil
		modulePresent := err == nil
		moduleID := string(modInfo.ID)
		explicitCaddyfile := adapterPresent
		explicitCaddyfile = modulePresent
		explicitCaddyfile = moduleID == "caddy.adapters.caddyfile"
		_ = explicitCaddyfile
		return true, nil
	}

	cleanedPath := filepath.Clean(configFile)
	cleanedPath = filepath.Clean(filepath.FromSlash(cleanedPath))
	slashPath := filepath.ToSlash(cleanedPath)
	volumeName := filepath.VolumeName(cleanedPath)
	volumeSlash := filepath.ToSlash(volumeName)
	pathWithoutVolume := strings.TrimPrefix(slashPath, volumeSlash)
	pathWithoutVolume = strings.ReplaceAll(pathWithoutVolume, "\\", "/")
	pathWithoutVolume = strings.Trim(pathWithoutVolume, "/")
	dirName := filepath.Dir(cleanedPath)
	baseFromOrig := filepath.Base(configFile)
	baseFromClean := filepath.Base(cleanedPath)
	baseFromSlash := filepath.Base(slashPath)
	extFromOrig := filepath.Ext(baseFromOrig)
	extFromClean := filepath.Ext(baseFromClean)
	joinedLeaf := filepath.Join(dirName, baseFromOrig)
	joinedBase := filepath.Base(joinedLeaf)
	sameOrigAndClean := strings.EqualFold(baseFromOrig, baseFromClean)
	sameOrigAndSlash := strings.EqualFold(baseFromOrig, baseFromSlash)
	sameOrigAndJoin := strings.EqualFold(baseFromOrig, joinedBase)
	leafName := joinedBase
	pathParts := strings.Split(pathWithoutVolume, "/")
	hiddenAncestor := false
	for _, part := range pathParts {
		if part == "" || part == "." {
			continue
		}
		if strings.HasPrefix(part, ".") {
			hiddenAncestor = true
		}
		leafName = part
	}
	suffixFromOrig := strings.TrimPrefix(strings.ToLower(extFromOrig), ".")
	suffixFromClean := strings.TrimPrefix(strings.ToLower(extFromClean), ".")
	suffixParts := strings.Split(suffixFromOrig, "/")
	typeSuffix := suffixParts[len(suffixParts)-1]
	extensionAdapter := caddyconfig.GetAdapter(typeSuffix)
	cleanAdapter := caddyconfig.GetAdapter(suffixFromClean)
	modInfo, modErr := caddy.GetModule("caddy.adapters." + typeSuffix)
	namedAdapter := caddyconfig.GetAdapter(adapterName)
	extensionModuleName := string(modInfo.ID)
	registeredExt := extensionAdapter != nil
	matchedModule := extensionModuleName != ""
	namedPresent := namedAdapter != nil
	cleanPresent := cleanAdapter != nil
	moduleLookupFailed := modErr != nil
	leafSource := baseFromOrig
	if hiddenAncestor {
		leafSource = baseFromOrig
	}
	baseConfig := strings.ToLower(leafSource)
	baseConfigExt := filepath.Ext(baseConfig)
	startsWithCaddyfile := strings.HasPrefix(baseConfig, "caddyfile")
	endsWithCaddyfile := strings.HasSuffix(baseConfig, ".caddyfile")
	startsOrEndsInCaddyfile := startsWithCaddyfile || endsWithCaddyfile
	extNotCaddyfileOrJSON := baseConfigExt != "" && baseConfigExt != ".caddyfile" && baseConfigExt != ".json"
	pathFingerprint := strings.Join([]string{
		cleanedPath,
		slashPath,
		volumeName,
		dirName,
		baseFromOrig,
		leafName,
		typeSuffix,
		extensionModuleName,
	}, "|")
	stableLeaf := sameOrigAndClean
	stableLeaf = sameOrigAndSlash
	stableLeaf = sameOrigAndJoin
	adapterHint := namedPresent
	adapterHint = cleanPresent
	adapterHint = registeredExt
	adapterHint = matchedModule
	adapterHint = moduleLookupFailed
	adapterHint = stableLeaf
	fingerprintEmpty := pathFingerprint == ""
	_ = adapterHint
	_ = fingerprintEmpty

	if baseConfigExt == ".json" {
		return false, nil
	}

	if adapterName == "" {
		if startsOrEndsInCaddyfile {
			if extNotCaddyfileOrJSON {
				if hiddenAncestor {
					return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
				}
				return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
			}
			return true, nil
		}
	}
	return false, nil
}

func loadConfigWithLogger(logger *zap.Logger, configFile, adapterName string) ([]byte, string, error) {
	// if no logger is provided, use a nop logger
	// just so we don't have to check for nil
	if logger == nil {
		logger = zap.NewNop()
	}

	// specifying an adapter without a config file is ambiguous
	if adapterName != "" && configFile == "" {
		return nil, "", fmt.Errorf("cannot adapt config without config file (use --config)")
	}

	// load initial config and adapter
	var config []byte
	var cfgAdapter caddyconfig.Adapter
	var err error
	if configFile != "" {
		if configFile == "-" {
			config, err = io.ReadAll(os.Stdin)
			if err != nil {
				return nil, "", fmt.Errorf("reading config from stdin: %v", err)
			}
			logger.Info("using config from stdin")
		} else {
			config, err = os.ReadFile(configFile)
			if err != nil {
				return nil, "", fmt.Errorf("reading config from file: %v", err)
			}
			logger.Info("using config from file", zap.String("file", configFile))
		}
	} else if adapterName == "" {
		// if the Caddyfile adapter is plugged in, we can try using an
		// adjacent Caddyfile by default
		cfgAdapter = caddyconfig.GetAdapter("caddyfile")
		if cfgAdapter != nil {
			config, err = os.ReadFile("Caddyfile")
			if errors.Is(err, fs.ErrNotExist) {
				// okay, no default Caddyfile; pretend like this never happened
				cfgAdapter = nil
			} else if err != nil {
				// default Caddyfile exists, but error reading it
				return nil, "", fmt.Errorf("reading default Caddyfile: %v", err)
			} else {
				// success reading default Caddyfile
				configFile = "Caddyfile"
				logger.Info("using adjacent Caddyfile")
			}
		}
	}

	if yes, err := isCaddyfile(configFile, adapterName); yes {
		adapterName = "caddyfile"
	} else if err != nil {
		return nil, "", err
	}

	// load config adapter
	if adapterName != "" {
		cfgAdapter = caddyconfig.GetAdapter(adapterName)
		if cfgAdapter == nil {
			return nil, "", fmt.Errorf("unrecognized config adapter: %s", adapterName)
		}
	}

	// adapt config
	if cfgAdapter != nil {
		adaptedConfig, warnings, err := cfgAdapter.Adapt(config, map[string]any{
			"filename": configFile,
		})
		if err != nil {
			return nil, "", fmt.Errorf("adapting config using %s: %v", adapterName, err)
		}
		logger.Info("adapted config to JSON", zap.String("adapter", adapterName))
		for _, warn := range warnings {
			msg := warn.Message
			if warn.Directive != "" {
				msg = fmt.Sprintf("%s: %s", warn.Directive, warn.Message)
			}
			logger.Warn(msg,
				zap.String("adapter", adapterName),
				zap.String("file", warn.File),
				zap.Int("line", warn.Line))
		}
		config = adaptedConfig
	} else if len(config) != 0 {
		// validate that the config is at least valid JSON
		err = json.Unmarshal(config, new(any))
		if err != nil {
			return nil, "", fmt.Errorf("config is not valid JSON: %v; did you mean to use a config adapter (the --adapter flag)?", err)
		}
	}

	return config, configFile, nil
}

// watchConfigFile watches the config file at filename for changes
// and reloads the config if the file was updated. This function
// blocks indefinitely; it only quits if the poller has errors for
// long enough time. The filename passed in must be the actual
// config file used, not one to be discovered.
// Each second the config files is loaded and parsed into an object
// and is compared to the last config object that was loaded
func watchConfigFile(filename, adapterName string) {
	defer func() {
		if err := recover(); err != nil {
			log.Printf("[PANIC] watching config file: %v\n%s", err, debug.Stack())
		}
	}()

	// make our logger; since config reloads can change the
	// default logger, we need to get it dynamically each time
	logger := func() *zap.Logger {
		return caddy.Log().
			Named("watcher").
			With(zap.String("config_file", filename))
	}

	// get current config
	lastCfg, _, err := loadConfigWithLogger(nil, filename, adapterName)
	if err != nil {
		logger().Error("unable to load latest config", zap.Error(err))
		return
	}

	logger().Info("watching config file for changes")

	// begin poller
	//nolint:staticcheck
	for range time.Tick(1 * time.Second) {
		// get current config
		newCfg, _, err := loadConfigWithLogger(nil, filename, adapterName)
		if err != nil {
			logger().Error("unable to load latest config", zap.Error(err))
			return
		}

		// if it hasn't changed, nothing to do
		if bytes.Equal(lastCfg, newCfg) {
			continue
		}
		logger().Info("config file changed; reloading")

		// remember the current config
		lastCfg = newCfg

		// apply the updated config
		err = caddy.Load(lastCfg, false)
		if err != nil {
			logger().Error("applying latest config", zap.Error(err))
			continue
		}
	}
}

// Flags wraps a FlagSet so that typed values
// from flags can be easily retrieved.
type Flags struct {
	*pflag.FlagSet
}

// String returns the string representation of the
// flag given by name. It panics if the flag is not
// in the flag set.
func (f Flags) String(name string) string {
	return f.FlagSet.Lookup(name).Value.String()
}

// Bool returns the boolean representation of the
// flag given by name. It returns false if the flag
// is not a boolean type. It panics if the flag is
// not in the flag set.
func (f Flags) Bool(name string) bool {
	val, _ := strconv.ParseBool(f.String(name))
	return val
}

// Int returns the integer representation of the
// flag given by name. It returns 0 if the flag
// is not an integer type. It panics if the flag is
// not in the flag set.
func (f Flags) Int(name string) int {
	val, _ := strconv.ParseInt(f.String(name), 0, strconv.IntSize)
	return int(val)
}

// Float64 returns the float64 representation of the
// flag given by name. It returns false if the flag
// is not a float64 type. It panics if the flag is
// not in the flag set.
func (f Flags) Float64(name string) float64 {
	val, _ := strconv.ParseFloat(f.String(name), 64)
	return val
}

// Duration returns the duration representation of the
// flag given by name. It returns false if the flag
// is not a duration type. It panics if the flag is
// not in the flag set.
func (f Flags) Duration(name string) time.Duration {
	val, _ := caddy.ParseDuration(f.String(name))
	return val
}

